const body = $input.first().json.body;

const required = ['incident_title', 'severity', 'started_at', 'resolved_at', 'summary', 'timeline'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

const validSeverities = ['SEV1', 'SEV2', 'SEV3', 'P0', 'P1', 'P2', 'critical', 'high', 'medium'];
if (!validSeverities.includes(body.severity)) {
  return [{ json: { valid: false, error: `severity must be one of: ${validSeverities.join(', ')}` } }];
}

const start = new Date(body.started_at);
const end = new Date(body.resolved_at);
if (isNaN(start) || isNaN(end)) {
  return [{ json: { valid: false, error: 'started_at and resolved_at must be valid ISO timestamps' } }];
}

const durationMs = end - start;
const durationMins = Math.round(durationMs / 60000);
const durationHuman = durationMins < 60
  ? `${durationMins} minutes`
  : `${Math.floor(durationMins / 60)}h ${durationMins % 60}m`;

return [{
  json: {
    valid: true,
    incidentTitle: body.incident_title,
    severity: body.severity,
    startedAt: body.started_at,
    resolvedAt: body.resolved_at,
    durationMins,
    durationHuman,
    summary: body.summary.slice(0, 2000),
    timeline: Array.isArray(body.timeline) ? body.timeline.slice(0, 30) : [],
    affectedSystems: body.affected_systems || [],
    impactDescription: body.impact_description || '',
    team: body.team || 'Engineering',
    incidentCommander: body.incident_commander || '',
    slackThread: body.slack_thread_url || null,
    outputFormat: body.output_format || 'markdown',
    notifyEmail: body.notify_email || null,
    notifySlack: body.notify_slack_channel || null
  }
}];

const rawMd = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const data = $('Validate & Enrich').first().json;

// Simple md → HTML for email
function mdToHtml(md) {
  return md
    .replace(/^# (.+)$/gm, '<h1 style="font-size:22px;margin:0 0 8px">$1</h1>')
    .replace(/^## (.+)$/gm, '<h2 style="font-size:16px;margin:24px 0 8px;color:#111;border-bottom:1px solid #e0e0e0;padding-bottom:4px">$1</h2>')
    .replace(/^\*\*(.+?)\*\*/gm, '<strong>$1</strong>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/^\| (.+) \|$/gm, (line) => {
      const cells = line.split('|').filter(c => c.trim());
      const isHeader = cells.every(c => /^[-: ]+$/.test(c.trim()));
      if (isHeader) return '';
      const tag = 'td';
      return '<tr>' + cells.map(c => `<${tag} style="padding:6px 10px;border:1px solid #ddd">${c.trim()}</${tag}>`).join('') + '</tr>';
    })
    .replace(/(<tr>.*<\/tr>\n?)+/gs, t => `<table style="border-collapse:collapse;width:100%;margin:12px 0;font-size:13px">${t}</table>`)
    .replace(/^- (.+)$/gm, '<li style="margin-bottom:4px">$1</li>')
    .replace(/(<li[^>]*>.*<\/li>\n?)+/gs, s => `<ul style="padding-left:20px;margin:8px 0">${s}</ul>`)
    .replace(/\n\n/g, '</p><p style="margin:0 0 12px">')
    .replace(/\n/g, '<br>');
}

const severityColors = {
  SEV1: '#dc2626', P0: '#dc2626', critical: '#dc2626',
  SEV2: '#ea580c', P1: '#ea580c', high: '#ea580c',
  SEV3: '#ca8a04', P2: '#ca8a04', medium: '#ca8a04'
};
const severityColor = severityColors[data.severity] || '#6b7280';

const htmlEmail = `<!DOCTYPE html><html><head><meta charset="utf-8"></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1a1a1a;background:#f5f5f4;margin:0;padding:24px">
<div style="max-width:700px;margin:0 auto;background:#fff;border-radius:8px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,0.08)">
  <div style="background:#111;color:#fff;padding:20px 28px;display:flex;align-items:center;gap:12px">
    <span style="background:${severityColor};color:#fff;font-size:11px;font-weight:700;padding:3px 8px;border-radius:4px;font-family:monospace">${data.severity}</span>
    <span style="font-size:15px;font-weight:500">${data.incidentTitle}</span>
    <span style="margin-left:auto;color:#888;font-size:12px;font-family:monospace">${data.durationHuman}</span>
  </div>
  <div style="padding:28px">
    <p style="margin:0 0 12px">${mdToHtml(rawMd)}</p>
  </div>
  <div style="background:#f5f5f4;padding:14px 28px;font-size:11px;color:#888;font-family:monospace">
    Generated by Outage Postmortem Generator · ${new Date().toISOString()}
  </div>
</div>
</body></html>`;

return [{
  json: {
    markdown: rawMd,
    htmlEmail,
    incidentTitle: data.incidentTitle,
    severity: data.severity,
    notifyEmail: data.notifyEmail,
    notifySlack: data.notifySlack,
    slackThread: data.slackThread
  }
}];

